```typescript
import { type Plugin, tool } from "@opencode-ai/plugin";
import { homedir } from "node:os";

const STATE_PATH = `${homedir()}/.local/share/opencode/phase0-state.json`;
const CONFIG_PATH = `${homedir()}/.config/opencode/opencode.json`;
const DB_PATH = `${homedir()}/.local/share/opencode/opencode.db`;

// Инструменты, доступные до выполнения CYCLE 1
const PHASE0_ALLOWED = new Set([
  "memory_search",
  "skill",
  "read",
  "phase0_complete",
]);

interface State {
  cycle1Completed: boolean;
  sessionId: string | null;
  lastAgentId: string | null;
  lastAgentCheck: number;
}

export default (async ({ $, client }) => {
  const sh = $;

  // --- Load state ---
  let state: State = {
    cycle1Completed: false,
    sessionId: null,
    lastAgentId: null,
    lastAgentCheck: 0,
  };

  try {
    const f = Bun.file(STATE_PATH);
    if (await f.exists()) {
      state = { ...state, ...JSON.parse(await f.text()) };
    }
  } catch { /* first run */ }

  // --- Load agent permissions from config ---
  let agentConfig: Record<string, any> = {};
  try {
    const f = Bun.file(CONFIG_PATH);
    if (await f.exists()) {
      const config = JSON.parse(await f.text());
      agentConfig = config.agent || {};
    }
  } catch (e) {
    void client.app.log({
      body: { service: "phase0-guard", level: "error", message: `config: ${e}` }
    });
  }

  async function persist() {
    try { await Bun.write(STATE_PATH, JSON.stringify(state, null, 2)); }
    catch {}
  }

  // Check if a tool+agent combo is allowed
  function isAllowed(toolName: string, agentId: string): boolean {
    const agent = agentConfig[agentId];
    if (!agent) return true;

    const perms = agent.permission;
    if (!perms) return true;

    // Check deny rules first
    for (const [key, rule] of Object.entries(perms)) {
      if (typeof rule === "string" && rule === "deny") {
        if (toolName === key) return false;
        if (key.endsWith("*") && toolName.startsWith(key.slice(0, -1))) return false;
        if (key.startsWith("*") && toolName.endsWith(key.slice(1))) return false;
      }
      if (typeof rule === "object" && rule !== null) {
        for (const [pat, action] of Object.entries(rule)) {
          const matched = pat === "*" || 
            (pat.endsWith("*") && toolName.startsWith(pat.slice(0, -1))) ||
            toolName === pat;
          if (matched) return action === "allow";
        }
      }
    }

    // Check tools (MCP tools)
    const tools = agent.tools;
    if (tools) {
      let found = false;
      for (const [key, allowed] of Object.entries(tools)) {
        if (key.endsWith("*") && toolName.startsWith(key.slice(0, -1))) {
          found = true;
          if (!allowed) return false;
        }
      }
      // Если инструмент найден в tools и не разрешён — запрещён
      // Если не найден — смотрим permissions (уже проверили выше)
    }

    return true;
  }

  // Get current agent ID from DB (cached)
  async function getCurrentAgent(): Promise<string | null> {
    const now = Date.now();
    if (state.lastAgentId && (now - state.lastAgentCheck) < 10000) {
      return state.lastAgentId;
    }

    try {
      const r = await sh`sqlite3 ${DB_PATH} "SELECT agent_id FROM session WHERE parent_id IS NULL ORDER BY time_updated DESC LIMIT 1"`.quiet().nothrow();
      const agentId = r.stdout?.toString().trim() || null;
      if (agentId) {
        state.lastAgentId = agentId;
        state.lastAgentCheck = now;
      }
      return agentId;
    } catch {
      return null;
    }
  }

  return {
    tool: {
      phase0_complete: tool({
        description: "Подтвердить выполнение CYCLE 1. Снимает Phase 0 guard и разблокирует все инструменты. Вызывать ТОЛЬКО после memory_search + skill('jarvis-cycles').",
        args: {},
        async execute() {
          state.cycle1Completed = true;
          await persist();
          return "✅ Phase 0 guard снят. Все инструменты разблокированы.";
        },
      }),
    },

    "tool.execute.before": async (input, output) => {
      try {
        // === Phase 0 guard ===
        if (!state.cycle1Completed) {
          if (!PHASE0_ALLOWED.has(input.tool)) {
            output.isError = true;
            output.content = `⛔ [PHASE 0 GUARD] '${input.tool}' заблокирован.

CYCLE 1 не выполнен. Обязательный протокол при старте:
  1. memory_search("") — проверка памяти
  2. skill("jarvis-cycles") — загрузка протокола
  3. phase0_complete — подтверждение и разблокировка

Доступно сейчас: memory_search, skill, read, phase0_complete`;
            return;
          }
          return; // разрешено
        }

        // === Pre-flight check ===
        const agentId = await getCurrentAgent();
        if (agentId && !isAllowed(input.tool, agentId)) {
          output.isError = true;
          output.content = `⛔ [PRE-FLIGHT] '${input.tool}' не разрешён для агента '${agentId}'.

Делегируйте задачу через task() агенту с доступом к '${input.tool}'.`;
          return;
        }
      } catch (e) {
        void client.app.log({
          body: { service: "phase0-guard", level: "error", message: `before: ${e}` }
        });
      }
    },

    event: async ({ event }) => {
      try {
        if (event.type === "session.created") {
          state.cycle1Completed = false;
          state.sessionId = (event.properties as any)?.sessionID || null;
          await persist();

          void client.app.log({
            body: { service: "phase0-guard", level: "info", message: "Phase 0 reset for new session" }
          });
        }
      } catch (e) {
        void client.app.log({
          body: { service: "phase0-guard", level: "error", message: `event: ${e}` }
        });
      }
    },
  };
}) satisfies Plugin;
```

